    1	package hotel.reservations;
    2	
    3	import hotel.rooms.Room;
    4	import java.math.BigDecimal;
    5	import java.math.RoundingMode;
    6	import java.time.DayOfWeek;
    7	import java.time.LocalDate;
    8	import java.time.Month;
    9	import java.util.Map;
   10	
   11	/**
   12	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   13	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   14	 * (half-even) at every step.
   15	 */
   16	public final class PriceCalculator {
   17	
   18	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   19	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
   20	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
   21	
   22	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
   23	            "TECNOSUL", new BigDecimal("0.12"),
   24	            "AGROVALE", new BigDecimal("0.18"),
   25	            "FARMAVIDA", new BigDecimal("0.25"));
   26	
   27	    static final Map<String, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
   28	            "STANDARD", new BigDecimal("520.00"),
   29	            "DELUXE", new BigDecimal("820.00"),
   30	            "SUITE", new BigDecimal("1200.00"));
   31	
   32	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   33	        return calculate(room, checkIn, checkOut, ratePlan, null);
   34	    }
   35	
   36	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   37	        return switch (ratePlan) {
   38	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
   39	            default -> calculateNormal(room, checkIn, checkOut, ratePlan, companyCode);
   40	        };
   41	    }
   42	
   43	    private Price calculateNormal(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   44	        int nights = 0;
   45	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   46	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   47	            subtotal = subtotal.add(nightPrice(room, night));
   48	            nights++;
   49	        }
   50	        BigDecimal discount = switch (ratePlan) {
   51	            case STANDARD -> cents(BigDecimal.ZERO);
   52	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   53	            case CORPORATE -> cents(subtotal.multiply(CORPORATE_DISCOUNTS.get(companyCode)));
   54	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
   55	            case WEEKEND_PACKAGE -> throw new AssertionError("Should be handled by calculateWeekendPackage");
   56	        };
   57	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   58	    }
   59	
   60	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
   61	        String roomType = room.type().toString();
   62	        BigDecimal fixedPrice = WEEKEND_PACKAGE_PRICES.get(roomType);
   63	        return new Price(2, fixedPrice, cents(BigDecimal.ZERO), fixedPrice);
   64	    }
   65	
   66	    BigDecimal nightPrice(Room room, LocalDate night) {
   67	        BigDecimal nightlyRate = room.nightlyRate();
   68	        if (isHighSeason(night)) {
   69	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   70	        }
   71	        return cents(nightlyRate);
   72	    }
   73	
   74	    /** High season: from December 15 to the end of February, and the whole of July. */
   75	    static boolean isHighSeason(LocalDate date) {
   76	        Month month = date.getMonth();
   77	        return month == Month.JANUARY
   78	                || month == Month.FEBRUARY
   79	                || month == Month.JULY
   80	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   81	    }
   82	
   83	    static boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
   84	        if (!checkOut.equals(checkIn.plusDays(2))) {
   85	            return false;
   86	        }
   87	        return checkIn.getDayOfWeek() == DayOfWeek.FRIDAY
   88	                && checkOut.getDayOfWeek() == DayOfWeek.SUNDAY;
   89	    }
   90	
   91	    static BigDecimal cents(BigDecimal value) {
   92	        return value.setScale(2, RoundingMode.HALF_EVEN);
   93	    }
   94	}
 20     public ReservationService(
 21             Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 22         this.rooms = rooms;
 23         this.store = store;
 24         this.priceCalculator = priceCalculator;
 25         this.emailSender = emailSender;
 26     }
 27 
 28     public synchronized Reservation create(NewReservation request) {
 29         if (!request.checkOut().isAfter(request.checkIn())) {
 30             throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 31         }
 32         if (request.guests() < 1) {
 33             throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 34         }
 35 
 36         validateRatePlan(request);
 37 
 38         Room room = rooms.find(request.roomNumber())
 39                 .orElseThrow(() -> new HotelException(
 40                         ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 41         if (request.guests() > room.capacity()) {
 42             throw new HotelException(
 43                     ErrorCode.CAPACITY_EXCEEDED,
 44                     "room " + room.number() + " takes at most " + room.capacity() + " guests");
 45         }
 46         if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 47             throw new HotelException(
 48                     ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 49         }
 50         Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 51         return store.add(request, price);
 52     }
 53 
 54     private void validateRatePlan(NewReservation request) {
 55         switch (request.ratePlan()) {
 56             case CORPORATE -> {
 57                 if (request.companyCode() == null || !isValidCompanyCode(request.companyCode())) {
 58                     throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code for CORPORATE rate");
 59                 }
 60             }
 61             case WEEKEND_PACKAGE -> {
 62                 if (!PriceCalculator.isWeekendPackageValid(request.checkIn(), request.checkOut())) {
 63                     throw new HotelException(ErrorCode.INVALID_REQUEST, "WEEKEND_PACKAGE requires Friday to Sunday (2 nights)");
 64                 }
 65             }
 66             case LONG_STAY -> {
 67                 int nights = 0;
 68                 for (LocalDate night = request.checkIn(); night.isBefore(request.checkOut()); night = night.plusDays(1)) {
 69                     nights++;
 70                 }
 71                 if (nights < 7) {
 72                     throw new HotelException(ErrorCode.INVALID_REQUEST, "LONG_STAY requires at least 7 nights");
 73                 }
 74             }
 75             default -> {
 76             }
 77         }
 78     }
 79 
 80     private boolean isValidCompanyCode(String code) {
 81         return code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA");
 82     }
 83 
 84     public Reservation find(long reservationId) {
 85         return store.find(reservationId)
 86                 .orElseThrow(() -> new HotelException(
 87                         ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 88     }
 89 
 90     /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 91     public synchronized Reservation confirm(long reservationId) {
 92         Reservation reservation = find(reservationId);
 93         if (reservation.status() != ReservationStatus.PENDING) {
 94             throw notAllowed(reservation, "confirm");
 95         }
 96         reservation.confirmPayment();
 97         store.update(reservation);
 98         ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 99         emailSender.send(
100                 reservation.guest().email(),
101                 "Reserva confirmada - " + HOTEL_NAME,
102                 confirmationEmailBody(reservation, receipt));
103         return reservation;
104     }
105 
106     /**
107      * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
108      * reservation was never paid, so nothing comes back).
109      */
110     public synchronized Reservation cancel(long reservationId) {
111         Reservation reservation = find(reservationId);
112         if (reservation.status() != ReservationStatus.PENDING
113                 && reservation.status() != ReservationStatus.CONFIRMED) {
114             throw notAllowed(reservation, "cancel");
115         }
116         BigDecimal refund = switch (reservation.ratePlan()) {
117             case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
118             case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
119             case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
120         };
121         reservation.cancel(refund);
122         store.update(reservation);
123         return reservation;
124     }
125 
126     public synchronized Reservation checkIn(long reservationId) {
127         Reservation reservation = find(reservationId);
128         if (reservation.status() != ReservationStatus.CONFIRMED) {
129             throw notAllowed(reservation, "check in");
130         }
131         reservation.changeStatus(ReservationStatus.CHECKED_IN);
132         store.update(reservation);
133         return reservation;
134     }
